using System;
using System.Collections.Generic;
using System.Linq;
using System.Text.RegularExpressions;
using System.Threading.Tasks;
using TCAdmin.GameHosting.SDK.RconProviders;
using TCAdmin.GameHosting.SDK.RconProviders.Source;

var Globals = new TCAdmin.Scripting.Engines.Addons.CSharpGameGlobals(); // DO NOT MODIFY THIS LINE

var action = Variables.Parse("RconAction", "status");
var target = Variables.Parse("RconTarget", "");
var value = Variables.Parse("RconValue", "");

string Clean(string s)
{
    s = s ?? "";
    s = s.Replace("\r", " ").Replace("\n", " ").Replace(";", " ").Replace("\"", "'");
    return s.Trim();
}
var rawTarget = (target ?? "").Replace("\r", " ").Replace("\n", " ").Trim();
target = Clean(target);
value = Clean(value);

async Task<T> WithTimeout<T>(Task<T> task, int ms, string what)
{
    if (await Task.WhenAny(task, Task.Delay(ms)) != task) throw new Exception(what + " timed out.");
    return await task;
}

// One RCON connection per run, opened on first use; every reply is read straight off the socket.
SourceRconClient rcon = null;
async Task<string> Rcon(string cmd)
{
    if (rcon == null)
    {
        var factory = RconClientFactories.FirstOrDefault(f => f.Protocol == ThisGame.QueryRconProtocolConfig.RconProtocol);
        rcon = factory?.Create() as SourceRconClient
            ?? throw new Exception("This blueprint's RCON protocol must be 'source' (Valve Source RCON).");
        try
        {
            await rcon.ConnectAsync(ThisService.IPAddress, ThisService.RconPort, ThisService.Variables.Parse<string>("RconPassword", string.Empty));
        }
        catch (RconAuthenticationException)
        {
            throw new Exception("RCON refused the password. Restart the server so server.cfg picks up the panel's RCON password.");
        }
    }
    return await rcon.ExecuteCommandAsync(cmd);
}

IEnumerable<string> Lines(string text) => (text ?? "").Split('\n').Select(l => l.TrimEnd('\r'));

// srcds `status` rows: #  2 "Bot01" BOT active  /  #  3 "Name" STEAM_0:1:123 00:31 50 0 active ip:port
async Task<List<(int UserId, string Name, string SteamId)>> StatusRows()
{
    var rows = new List<(int, string, string)>();
    foreach (var line in Lines(await Rcon("status")))
    {
        var m = Regex.Match(line, "^#\\s*(\\d+)\\s+\"(.*)\"\\s+(BOT|STEAM_\\d+:\\d+:\\d+)\\b");
        if (m.Success) rows.Add((int.Parse(m.Groups[1].Value), m.Groups[2].Value, m.Groups[3].Value));
    }
    return rows;
}

async Task<Dictionary<string, int>> GetBotNames()
{
    var bots = new Dictionary<string, int>();
    foreach (var row in await StatusRows())
        if (row.SteamId == "BOT") bots[row.Name] = row.UserId;
    return bots;
}

try
{
    string svcStatus = "Unknown";
    try {
        var svcInfo = await WithTimeout(ServiceManagerService.GetServiceStatus(ThisService.ServiceId), 8000, "Status check");
        if (svcInfo != null) svcStatus = svcInfo.Status.ToString();
    } catch (Exception) { }
    var isRunning = svcStatus == "Started";
    if (!isRunning)
    {
        // Service is not running: never send RCON commands.
        if (action != "status") throw new Exception("The service is not running (" + svcStatus + "). RCON commands are disabled.");
        Globals.ReturnValue = new { running = false, serviceStatus = svcStatus, online = "Offline", hostname = "", map = "", numPlayers = 0, maxPlayers = 0, players = new object[0] };
    }
    else switch (action)
    {
        case "status":
        {
            var q = await WithTimeout(GameServiceManager.QueryService(ThisService), 10000, "Server query");
            var list = q.Players ?? new List<TCAdmin.SDK.Hubs.Models.GameQuery.GameQueryPlayer>();
            var botNames = list.Count > 0 ? await GetBotNames() : new Dictionary<string, int>();
            var players = list.Select(p => new { name = p.Name, score = p.Score, connectedSeconds = p.ConnectTime, isBot = botNames.ContainsKey(p.Name) }).ToList();
            Globals.ReturnValue = new { running = true, serviceStatus = svcStatus, online = q.Status, hostname = q.Name, map = q.Map, numPlayers = q.NumPlayers, maxPlayers = q.MaxPlayers, players };
            break;
        }
        case "convar":
        {
            var allowed = new[] { "sv_cheats", "sv_gravity", "sv_alltalk", "sbox_godmode", "sbox_noclip", "sbox_weapons", "sbox_playershurtplayers", "sbox_maxprops", "sv_friction", "phys_timescale", "host_timescale", "gmod_physiterations" };
            if (!allowed.Contains(target)) throw new Exception($"Setting '{target}' is not allowed.");
            if (!Regex.IsMatch(value, "^[A-Za-z0-9_.\\- ]{0,64}$")) throw new Exception("Invalid value.");
            await Rcon($"{target} \"{value}\"");
            Globals.ReturnValue = new { ok = true, command = $"{target} {value}" };
            break;
        }
        case "kick":
        {
            if (target == "") throw new Exception("Player name required.");
            var botIds = await GetBotNames();
            var isBotTarget = botIds.ContainsKey(rawTarget);
            // bot_kick does not exist in GMod; kick the bot by userid through Lua instead.
            await Rcon(isBotTarget ? $"lua_run local p=Player({botIds[rawTarget]}) if IsValid(p) then p:Kick() end" : $"kick \"{target}\" \"{value}\"");
            if (isBotTarget) { Globals.ReturnValue = new { ok = true, bot = true }; break; }
            // The drop can take a server frame or two to show in `status`.
            var stillConnected = true;
            for (var attempt = 0; attempt < 4 && stillConnected; attempt++)
            {
                if (attempt > 0) await Task.Delay(250);
                stillConnected = (await StatusRows()).Any(r => r.Name == target);
            }
            if (stillConnected)
                throw new Exception($"Kick sent, but '{target}' is still connected. The name may not match exactly - try again or use Ban.");
            Globals.ReturnValue = new { ok = true };
            break;
        }
        case "ban":
        {
            if (target == "") throw new Exception("Player name required.");
            var rows = await StatusRows();
            if (rows.Any(r => r.SteamId == "BOT" && r.Name == rawTarget)) throw new Exception("Bots cannot be banned. Use Kick instead.");
            var steamId = rows.Where(r => r.SteamId != "BOT" && r.Name == target).Select(r => r.SteamId).FirstOrDefault();
            if (steamId == null) throw new Exception("Could not find the player's SteamID in the server status. Use Kick instead.");
            var minutes = Regex.IsMatch(value, "^\\d{1,7}$") ? value : "0";
            await Rcon($"banid {minutes} {steamId} kick");
            await Rcon("writeid");
            Globals.ReturnValue = new { ok = true, steamId, minutes };
            break;
        }
        case "say":
        {
            if (value == "") throw new Exception("Message required.");
            await Rcon($"say \"{value}\"");
            Globals.ReturnValue = new { ok = true };
            break;
        }
        case "addbot":
        {
            if (rawTarget.Length < 1 || rawTarget.Length > 32) throw new Exception("Bot name must be 1-32 characters.");
            var luaName = rawTarget.Replace("\\", "\\\\").Replace("\"", "\\\"");
            await Rcon($"lua_run player.CreateNextBot(\"{luaName}\")");
            Globals.ReturnValue = new { ok = true, name = rawTarget };
            break;
        }
        case "convars":
        {
            // srcds returns what lua_run prints as the command's RCON reply.
            var output = await Rcon("lua_run for _,c in ipairs({\"sv_cheats\",\"sbox_godmode\",\"sbox_noclip\",\"sbox_weapons\",\"sbox_playershurtplayers\",\"sv_alltalk\",\"sv_gravity\",\"host_timescale\"}) do local v=GetConVar(c) if v then print(\"CVAR|\"..c..\"|\"..v:GetString()) end end");
            var cvList = new List<object>();
            foreach (var line in Lines(output))
            {
                var cm = Regex.Match(line, "^CVAR\\|([A-Za-z0-9_]+)\\|(.*?)\\s*$");
                if (cm.Success) cvList.Add(new { name = cm.Groups[1].Value, value = cm.Groups[2].Value });
            }
            Globals.ReturnValue = new { ok = true, convars = cvList };
            break;
        }
        case "maps":
        {
            var found = new SortedSet<string>(StringComparer.OrdinalIgnoreCase);
            foreach (var line in Lines(await Rcon("maps *")))
            {
                var mm = Regex.Match(line, "^(?:PENDING:)?\\s*\\(\\w+\\)\\s+(.+?)\\.bsp\\s*$");
                if (mm.Success) found.Add(mm.Groups[1].Value);
            }
            Globals.ReturnValue = new { ok = true, maps = found.ToArray() };
            break;
        }
        case "map":
        {
            if (!Regex.IsMatch(target, "^[A-Za-z0-9_\\-]{1,64}$")) throw new Exception("Invalid map name.");
            try { await Rcon($"changelevel {target}"); }
            // The server starts loading the map at once and may drop or stall the RCON reply.
            catch (Exception ex) when (ex is RconException || ex is OperationCanceledException) { }
            Globals.ReturnValue = new { ok = true };
            break;
        }
        default:
            throw new Exception($"Unknown action '{action}'.");
    }
}
finally
{
    if (rcon != null) await rcon.DisposeAsync();
}
